    if (!st) {
      // Starts full when a key first reaches it.
      this.states.set(key, { scaledTokens: this.scaledCapacity, lastTick: tick })
      return
    }
    const n = tick - st.lastTick
    if (n > 0n) {
      st.scaledTokens += this.refill * n
      if (st.scaledTokens > this.scaledCapacity) st.scaledTokens = this.scaledCapacity
    }
    st.lastTick = tick
  }

  canAllow(key) {
    const st = this.states.get(key)
    return st.scaledTokens >= this.per
  }

  record(key) {
    const st = this.states.get(key)
    st.scaledTokens -= this.per
  }
