import { isValidToken, parseUint } from './util.js'

const FIELD_MIN = {
  capacity: 1n,
  refill: 0n,
  per: 1n,
  limit: 0n,
  span: 1n,
  tick: 0n,
}

function parseField(str, field) {
  const v = parseUint(str)
  if (v === null || v < FIELD_MIN[field]) {
    throw new Error(`${field} must be an integer of at least ${FIELD_MIN[field]}`)
  }
  return v
}

export function parseProgram(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const policies = new Map()
  const routes = []
  const routePrefixes = new Set()
  const events = []
  let eventSeen = false
  let lastTick = null

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const tokens = trimmed.split(/\s+/)
    const kw = tokens[0]

    try {
      if (kw === 'bucket') {
        if (eventSeen) throw new Error('declarations must come before the first event')
        if (tokens.length !== 5) throw new Error('expected bucket <name> <capacity> <refill> <per>')
        const [, name, capStr, refillStr, perStr] = tokens
        if (!isValidToken(name)) throw new Error(`invalid policy name ${name}`)
        if (policies.has(name)) throw new Error(`policy ${name} is declared twice`)
        const capacity = parseField(capStr, 'capacity')
        const refill = parseField(refillStr, 'refill')
        const per = parseField(perStr, 'per')
        policies.set(name, { type: 'bucket', capacity, refill, per })
      } else if (kw === 'window') {
        if (eventSeen) throw new Error('declarations must come before the first event')
        if (tokens.length !== 4) throw new Error('expected window <name> <limit> <span>')
        const [, name, limitStr, spanStr] = tokens
        if (!isValidToken(name)) throw new Error(`invalid policy name ${name}`)
        if (policies.has(name)) throw new Error(`policy ${name} is declared twice`)
        const limit = parseField(limitStr, 'limit')
        const span = parseField(spanStr, 'span')
        policies.set(name, { type: 'window', limit, span })
      } else if (kw === 'route') {
        if (eventSeen) throw new Error('declarations must come before the first event')
        if (tokens.length < 3) throw new Error('expected route <prefix> <policy>...')
        const prefix = tokens[1]
        const policyNames = tokens.slice(2)
        if (!isValidToken(prefix)) throw new Error(`invalid route prefix ${prefix}`)
        if (routePrefixes.has(prefix)) throw new Error(`prefix ${prefix} is routed twice`)
        for (const pn of policyNames) {
          if (!policies.has(pn)) throw new Error(`unknown policy ${pn}`)
        }
        routePrefixes.add(prefix)
        routes.push({ prefix, policyNames })
      } else if (kw === 'event') {
        if (tokens.length !== 3) throw new Error('expected event <tick> <key>')
        const [, tickStr, key] = tokens
        const tick = parseField(tickStr, 'tick')
        if (lastTick !== null && tick < lastTick) {
          throw new Error(`tick ${tick} is before tick ${lastTick}`)
        }
        if (!isValidToken(key)) throw new Error(`invalid key ${key}`)
        eventSeen = true
        lastTick = tick
        events.push({ tick, key })
      } else {
        throw new Error(`unknown directive ${kw}`)
      }
    } catch (e) {
      throw new Error(`line ${lineNo}: ${e.message}`)
    }
  }

  return { policies, routes, events }
}
