/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */

import { parseProgram } from './parser.js'
import { simulate } from './simulate.js'

function readStdin() {
  return new Promise((resolve, reject) => {
    let data = ''
    process.stdin.setEncoding('utf8')
    process.stdin.on('data', (chunk) => {
      data += chunk
    })
    process.stdin.on('end', () => resolve(data))
    process.stdin.on('error', reject)
  })
}

async function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'replay' && args[0] !== 'summary')) {
    process.stderr.write('error: usage: cli.js replay|summary\n')
    process.exitCode = 2
    return
  }
  const mode = args[0]
  const text = await readStdin()

  let program
  try {
    program = parseProgram(text)
  } catch (e) {
    process.stderr.write(`error: ${e.message}\n`)
    process.exitCode = 2
    return
  }

  const { results, perKey, totalAllowed, totalDenied } = simulate(program)

  let out = ''
  if (mode === 'replay') {
    for (const r of results) {
      if (r.allow) out += `${r.tick} ${r.key} allow\n`
      else out += `${r.tick} ${r.key} deny ${r.denyPolicy}\n`
    }
  } else {
    const keys = [...perKey.keys()].sort()
    for (const k of keys) {
      const s = perKey.get(k)
      out += `${k} allowed=${s.allowed} denied=${s.denied}\n`
    }
    out += `total allowed=${totalAllowed} denied=${totalDenied}\n`
  }

  process.stdout.write(out)
  process.exitCode = 0
}

main().catch((e) => {
  process.stderr.write(`error: ${e.message}\n`)
  process.exitCode = 2
})
"}

